using Godot;
using System;
using System.Linq;
using System.Collections.Generic;
public partial class MigrationScene {
 void ItemCatalogChecks(){var all=ExpeditionItemDefinition.All();MigrationChecks.Assert(all.Count==48&&all.Select(i=>i.Key).Distinct().Count()==all.Count,"Item catalogue completeness / keys");foreach(var item in all){var n=new Node3D();AddChild(n);ItemModel(n,item.Kind,item.Index,item.Tier);MigrationChecks.Assert(n.FindChildren("*","MeshInstance3D",true,false).OfType<MeshInstance3D>().Any(m=>m.Mesh!=null),"Missing item geometry / "+item.Key);n.Free();}foreach(var r in ExpeditionRecipe.All){string kind=r.Kind=="night"?"tuning":r.Kind;MigrationChecks.Assert(all.Any(i=>i.Kind==kind&&(kind=="armor"?i.Tier==r.Tier&&i.Index==r.Result:kind=="bench"?i.Tier==r.Tier:kind=="weapon"?i.Index==r.Result:true)),"Recipe has no item model / "+r.Name);}GD.Print("PASS / 48 item catalogue entries: unique keys, real mesh geometry and complete recipe model coverage");}
 async void CaptureItemCatalog(){try{
  testing=true;CloseMenu();paused=true;hudRoot.Visible=false;terrainRoot.Visible=worldRoot.Visible=buildRoot.Visible=false;if(distantTerrain!=null)distantTerrain.Visible=false;ClearEnemies();weaponRoot.Visible=false;game.World.Changes.Time=900;ItemCatalogChecks();
  var all=ExpeditionItemDefinition.All();int shot=0;foreach(var group in new[]{"weapon","armor","material","survival","bench","structure","tool"}){
   var items=all.Where(i=>group=="survival"?i.Kind is "bandage" or "food" or "water" or "bag" or "ammo" or "catalyst" or "tuning":i.Kind==group).ToList();var stage=new Node3D();AddChild(stage);Box(stage,new(0,-.06f,0),new(18,.12f,6),new(.16f,.20f,.19f));stage.AddChild(new DirectionalLight3D{RotationDegrees=new(-30,145,0),LightEnergy=.9f,LightColor=new(.72f,.83f,.85f)});
   for(int i=0;i<items.Count;i++){float x=((items.Count-1)*.5f-i)*1.6f;var n=new Node3D{Position=new(x,.02f,0)};stage.AddChild(n);ItemModel(n,items[i].Kind,items[i].Index,items[i].Tier);stage.AddChild(new Label3D{Text="T"+items[i].Tier+" / "+items[i].Name,Position=new(x,1.18f,0),FontSize=27,PixelSize=.0028f,Billboard=BaseMaterial3D.BillboardModeEnum.Enabled,Modulate=new(.86f,.82f,.65f)});}
   camera.Fov=38;camera.GlobalPosition=new(0,2.8f,-(items.Count*1.16f+2));camera.LookAt(new Vector3(0,.43f,0));await ArtShot($"items-{++shot:00}-{group}");stage.QueueFree();await ToSignal(GetTree(),SceneTree.SignalName.ProcessFrame);
  }
  terrainRoot.Visible=worldRoot.Visible=buildRoot.Visible=true;if(distantTerrain!=null)distantTerrain.Visible=true;paused=false;Teleport(ExpeditionWorld.SpawnX,ExpeditionWorld.SpawnZ);for(int i=0;i<7;i++)game.Craft.Materials[i]=24;game.Craft.BenchTier=game.Craft.UnlockedTier=3;coopRecipeChoice=7;ShowCrafting();await ArtShot("items-08-crafting-preview");game.Profile.Items.Add(new ExpeditionRelic{Id="catalog/armor",Name="Industrial chest plate",Origin="Field workshop",Level=3,Armor=32,Vitality=9});game.Profile.Equipped="catalog/armor";inventoryFilter="ARMOR";inventorySelected="catalog/armor";ComicEquipment();await ArtShot("items-09-inventory-preview");CloseMenu();GD.Print("PASS / complete item catalogue GPU captures");GetTree().Quit();
 }catch(Exception ex){GD.PushError(ex.ToString());GetTree().Quit(1);}}
 void ArtSleepingBag(Node3D n){var pad=Bevel(n,new(0,.12f,0),new(.78f,.24f,1.90f),Cloth);pad.MaterialOverride=Textured(Cloth,0,.65f);Tube(n,new(-.33f,.20f,-.72f),new(.33f,.20f,-.72f),.15f,new(.43f,.48f,.35f));for(int i=0;i<7;i++)Box(n,new(0,.247f,-.50f+i*.20f),new(.67f,.005f,.012f),new(.20f,.27f,.22f));for(int s=-1;s<=1;s+=2)Box(n,new(s*.35f,.20f,.18f),new(.015f,.015f,1.24f),Wood);}
}
